/*
 * Car Showroom Management System
 * Pure-C web server; HTML pages are generated by C.
 * Build: gcc server.c -o showroom.exe -lws2_32 (Windows)
 *        gcc server.c -o showroom (Linux/macOS)
 */
#ifdef _WIN32
#define _WIN32_WINNT 0x0600
#include <winsock2.h>
#include <ws2tcpip.h>
typedef SOCKET socket_t;
#define CLOSESOCK closesocket
#define SOCKERR SOCKET_ERROR
#else
#include <sys/types.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <unistd.h>
#include <signal.h>
typedef int socket_t;
#define INVALID_SOCKET (-1)
#define SOCKET_ERROR (-1)
#define CLOSESOCK close
#endif

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <ctype.h>
#include <time.h>
#include <stdarg.h>

static int PORT = 8080;
#define MAX_CARS 500
#define MAX_CUSTOMERS 500
#define MAX_SALES 500
#define REQ_SIZE 65536
#define OUT_SIZE 262144

typedef struct {
    int id;
    char brand[48], model[48], year[12], color[32], price[24], fuel[24], status[20];
} Car;
typedef struct {
    int id;
    char name[64], phone[24], email[80], address[120];
} Customer;
typedef struct {
    int id, car_id, customer_id;
    char date[20], amount[24], payment[24];
} Sale;

static Car cars[MAX_CARS]; static int car_count = 0, next_car_id = 1;
static Customer customers[MAX_CUSTOMERS]; static int customer_count = 0, next_customer_id = 1;
static Sale sales[MAX_SALES]; static int sale_count = 0, next_sale_id = 1;
static char output[OUT_SIZE];

static void copystr(char *dst, size_t n, const char *src) {
    if (!src) src = "";
    snprintf(dst, n, "%s", src);
}
static void html_escape(char *dst, size_t n, const char *src) {
    size_t j=0;
    for (size_t i=0; src && src[i] && j+7<n; i++) {
        const char *r=NULL;
        switch(src[i]) { case '&': r="&amp;"; break; case '<': r="&lt;"; break;
            case '>': r="&gt;"; break; case '"': r="&quot;"; break; case '\'': r="&#39;"; break; }
        if (r) { size_t k=strlen(r); memcpy(dst+j,r,k); j+=k; }
        else dst[j++]=src[i];
    }
    dst[j]='\0';
}
static void url_decode(char *s) {
    char *p=s, *q=s;
    while (*p) {
        if (*p=='+') { *q++=' '; p++; }
        else if (*p=='%' && isxdigit((unsigned char)p[1]) && isxdigit((unsigned char)p[2])) {
            char h[3]={p[1],p[2],0}; *q++=(char)strtol(h,NULL,16); p+=3;
        } else *q++=*p++;
    }
    *q=0;
}
static void field(const char *body, const char *key, char *out, size_t n) {
    out[0]=0;
    if (!body) return;
    char *tmp=(char*)malloc(strlen(body)+1); if(!tmp) return;
    strcpy(tmp,body);
    for(char *tok=strtok(tmp,"&"); tok; tok=strtok(NULL,"&")) {
        char *eq=strchr(tok,'='); if(!eq) continue; *eq++=0;
        url_decode(tok); url_decode(eq);
        if(strcmp(tok,key)==0) { copystr(out,n,eq); break; }
    }
    free(tmp);
}
static int number(const char *s) { return s ? atoi(s) : 0; }

static void load_data(void) {
    FILE *f=fopen("data/cars.csv","r");
    if(f) { char line[512]; while(fgets(line,sizeof line,f) && car_count<MAX_CARS) {
        Car *c=&cars[car_count]; char *p=strtok(line,"|\r\n"); if(!p) continue; c->id=atoi(p);
        #define GETC(x) do{p=strtok(NULL,"|\r\n");copystr(c->x,sizeof c->x,p?p:"");}while(0)
        GETC(brand); GETC(model); GETC(year); GETC(color); GETC(price); GETC(fuel); GETC(status);
        #undef GETC
        if(c->id>=next_car_id) next_car_id=c->id+1; car_count++;
    } fclose(f); }
    f=fopen("data/customers.csv","r");
    if(f) { char line[512]; while(fgets(line,sizeof line,f) && customer_count<MAX_CUSTOMERS) {
        Customer *c=&customers[customer_count]; char *p=strtok(line,"|\r\n"); if(!p) continue; c->id=atoi(p);
        #define GETU(x) do{p=strtok(NULL,"|\r\n");copystr(c->x,sizeof c->x,p?p:"");}while(0)
        GETU(name); GETU(phone); GETU(email); GETU(address);
        #undef GETU
        if(c->id>=next_customer_id) next_customer_id=c->id+1; customer_count++;
    } fclose(f); }
    f=fopen("data/sales.csv","r");
    if(f) { char line[256]; while(fgets(line,sizeof line,f) && sale_count<MAX_SALES) {
        Sale *s=&sales[sale_count]; char *p=strtok(line,"|\r\n"); if(!p) continue; s->id=atoi(p);
        p=strtok(NULL,"|\r\n"); s->car_id=p?atoi(p):0; p=strtok(NULL,"|\r\n"); s->customer_id=p?atoi(p):0;
        p=strtok(NULL,"|\r\n"); copystr(s->date,sizeof s->date,p?p:"");
        p=strtok(NULL,"|\r\n"); copystr(s->amount,sizeof s->amount,p?p:"");
        p=strtok(NULL,"|\r\n"); copystr(s->payment,sizeof s->payment,p?p:"");
        if(s->id>=next_sale_id) next_sale_id=s->id+1; sale_count++;
    } fclose(f); }
}
static void save_cars(void) {
    FILE *f=fopen("data/cars.csv","w"); if(!f)return;
    for(int i=0;i<car_count;i++) fprintf(f,"%d|%s|%s|%s|%s|%s|%s|%s\n",cars[i].id,cars[i].brand,cars[i].model,cars[i].year,cars[i].color,cars[i].price,cars[i].fuel,cars[i].status);
    fclose(f);
}
static void save_customers(void) {
    FILE *f=fopen("data/customers.csv","w"); if(!f)return;
    for(int i=0;i<customer_count;i++) fprintf(f,"%d|%s|%s|%s|%s\n",customers[i].id,customers[i].name,customers[i].phone,customers[i].email,customers[i].address);
    fclose(f);
}
static void save_sales(void) {
    FILE *f=fopen("data/sales.csv","w"); if(!f)return;
    for(int i=0;i<sale_count;i++) fprintf(f,"%d|%d|%d|%s|%s|%s\n",sales[i].id,sales[i].car_id,sales[i].customer_id,sales[i].date,sales[i].amount,sales[i].payment);
    fclose(f);
}
static Car *find_car(int id) { for(int i=0;i<car_count;i++)if(cars[i].id==id)return &cars[i]; return NULL; }
static Customer *find_customer(int id) { for(int i=0;i<customer_count;i++)if(customers[i].id==id)return &customers[i]; return NULL; }

static void add(char *dst, size_t cap, size_t *pos, const char *fmt, ...) {
    if(*pos>=cap-1)return;
    va_list ap; va_start(ap,fmt); int n=vsnprintf(dst+*pos,cap-*pos,fmt,ap); va_end(ap);
    if(n>0) *pos += (size_t)n < cap-*pos ? (size_t)n : cap-*pos-1;
}
